import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { Select } from '../..';

const MockOptions = () => (
  <>
    <Select.Option data-testid="apple" value="Apple">
      Apple
    </Select.Option>
    <Select.Option disabled data-testid="banana" value="Banana">
      Banana
    </Select.Option>
    <Select.Option value="Grape">Grape</Select.Option>
    <Select.Option value="Orange">Orange</Select.Option>
  </>
);

describe('Select', () => {
  const user = userEvent.setup();
  test('should render without props', () => {
    render(
      <Select.Root>
        <MockOptions />
      </Select.Root>
    );

    expect(screen.getByText('Select a value')).toBeInTheDocument();
  });

  test('should render with label', () => {
    render(
      <Select.Root label="This is a label">
        <MockOptions />
      </Select.Root>
    );

    expect(screen.getByText('This is a label')).toBeInTheDocument();
  });

  test('should render with hint', () => {
    render(
      <Select.Root hint="This is a hint">
        <MockOptions />
      </Select.Root>
    );

    expect(screen.getByText('This is a hint')).toBeInTheDocument();
  });

  test('should render with an error message', () => {
    render(
      <Select.Root label="This is a label" error="This is an error">
        <MockOptions />
      </Select.Root>
    );

    expect(screen.getByText('This is an error')).toBeInTheDocument();
  });

  test('should be able to open the dropdown and choose an option', async () => {
    render(
      <Select.Root placeholder="Choose a fruit">
        <MockOptions />
      </Select.Root>
    );
    const selectEl = screen.getByRole('combobox');
    await user.click(selectEl);

    expect(selectEl).toHaveAttribute('aria-expanded', 'true');
    const selectedOption = screen.getByText('Orange');
    expect(selectedOption).toBeVisible();
    await user.click(selectedOption);

    expect(selectEl).toHaveAttribute('aria-expanded', 'false');
    expect(screen.getByText('Orange')).toBeInTheDocument();
  });

  test('should Banana option be disabled', async () => {
    render(
      <Select.Root placeholder="Choose a fruit">
        <MockOptions />
      </Select.Root>
    );
    const selectEl = screen.getByRole('combobox');
    await user.click(selectEl);

    const disabledEl = screen.getByTestId('banana');
    expect(disabledEl).toHaveAttribute('aria-disabled', 'true');
  });

  test('should be disabled', () => {
    render(
      <Select.Root data-testid="select" disabled placeholder="Choose a fruit">
        <Select.Option data-testid="apple" value="Apple">
          Apple
        </Select.Option>
        <Select.Option disabled data-testid="banana" value="Banana">
          Banana
        </Select.Option>
        <Select.Option value="Grape">Grape</Select.Option>
        <Select.Option value="Orange">Orange</Select.Option>
      </Select.Root>
    );

    const selectEl = screen.getByRole('combobox');
    expect(selectEl).toBeDisabled();
  });

  test('should be able to call custom onChange passed as prop', async () => {
    const mockOnChange = jest.fn();
    render(
      <Select.Root placeholder="Choose a fruit" onChange={mockOnChange}>
        <MockOptions />
      </Select.Root>
    );

    const selectEl = screen.getByRole('combobox');
    await user.click(selectEl);
    const selectedOption = screen.getByText('Orange');
    expect(selectedOption).toBeVisible();
    await user.click(selectedOption);
    expect(mockOnChange).toHaveBeenCalledWith('Orange');
  });

  test('should be able to set a custom width', () => {
    const mockOnChange = jest.fn();
    render(
      <Select.Root placeholder="Choose a fruit" onChange={mockOnChange} width="200px">
        <MockOptions />
      </Select.Root>
    );

    const selectEl = screen.getByText('Choose a fruit');
    //! Skipping this line because of an open issue
    //! https://github.com/modulz/stitches/discussions/800
    // expect(selectEl).toHaveStyle('width: 200px');
    expect(selectEl).toBeInTheDocument();
  });

  test('should render with multi-select variant', async () => {
    const mockOnChange = jest.fn();
    render(
      <Select.Root placeholder="Choose a fruit" multiple onChange={mockOnChange}>
        <Select.Option value="Apple">Apple</Select.Option>
        <Select.Option value="Banana">Banana</Select.Option>
        <Select.Option value="Grape">Grape</Select.Option>
        <Select.Option value="Orange">Orange</Select.Option>
      </Select.Root>
    );

    const selectEl = screen.getByRole('combobox');
    await user.click(selectEl);
    expect(document.querySelectorAll('button')).toHaveLength(1);
    const selectedOption = screen.getByText('Orange');
    await user.click(selectedOption);
    expect(mockOnChange).toHaveBeenCalledWith(['Orange']);
  });

  test('should render multi-select disabled', () => {
    const mockOnChange = jest.fn();
    render(
      <Select.Root
        data-testid="select"
        placeholder="Choose a fruit"
        multiple
        disabled
        onChange={mockOnChange}
      >
        <Select.Option data-testid="apple" value="Apple">
          Apple
        </Select.Option>
        <Select.Option value="Banana">Banana</Select.Option>
        <Select.Option value="Grape">Grape</Select.Option>
        <Select.Option value="Orange">Orange</Select.Option>
      </Select.Root>
    );

    const selectEl = screen.getByRole('combobox');
    expect(selectEl).toBeDisabled();
  });

  test('should render multi-select variant and allow user to select multiple elements', async () => {
    const mockOnChange = jest.fn();
    render(
      <Select.Root
        placeholder="Choose a fruit"
        multiple
        onChange={mockOnChange}
        displayText="fruits selected"
      >
        <Select.Option value="Apple">Apple</Select.Option>
        <Select.Option data-testid="banana" value="Banana" disabled>
          Banana
        </Select.Option>
        <Select.Option value="Grape">Grape</Select.Option>
        <Select.Option value="Orange">Orange</Select.Option>
      </Select.Root>
    );

    const selectEl = screen.getByRole('combobox');
    await user.click(selectEl);
    const orangeOption = screen.getByText('Orange');
    await user.click(orangeOption);
    expect(mockOnChange).toHaveBeenCalledWith(['Orange']);
    const appleOption = screen.getByText('Apple');
    await user.click(appleOption);
    expect(mockOnChange).toHaveBeenCalledWith(['Orange', 'Apple']);
    expect(screen.getByText('2 fruits selected')).toBeInTheDocument();

    const disabledEl = screen.getByTestId('banana');
    expect(disabledEl).toHaveAttribute('aria-disabled', 'true');
  });

  test('should render multi-select variant and allow user to select multiple elements and remove them', async () => {
    const mockOnChange = jest.fn();
    render(
      <Select.Root
        placeholder="Choose a fruit"
        multiple
        onChange={mockOnChange}
        displayText="fruits selected"
      >
        <Select.Option value="Apple">Apple</Select.Option>
        <Select.Option data-testid="banana" value="Banana" disabled>
          Banana
        </Select.Option>
        <Select.Option value="Grape">Grape</Select.Option>
        <Select.Option value="Orange">Orange</Select.Option>
      </Select.Root>
    );

    const selectEl = screen.getByRole('combobox');
    await user.click(selectEl);
    const orangeOption = screen.getByText('Orange');
    await user.click(orangeOption);
    expect(mockOnChange).toHaveBeenCalledWith(['Orange']);

    const appleOption = screen.getByText('Apple');
    await user.click(appleOption);
    expect(mockOnChange).toHaveBeenCalledWith(['Orange', 'Apple']);

    const grapeOption = screen.getByText('Grape');
    await user.click(grapeOption);
    expect(mockOnChange).toHaveBeenCalledWith(['Orange', 'Apple', 'Grape']);

    await user.click(appleOption);
    expect(mockOnChange).toHaveBeenCalledWith(['Orange', 'Grape']);

    expect(screen.getByText('2 fruits selected')).toBeInTheDocument();

    const disabledEl = screen.getByTestId('banana');
    expect(disabledEl).toHaveAttribute('aria-disabled', 'true');
  });

  test('should change value with multiple prop and inside a form', async () => {
    const mockOnChange = jest.fn();
    render(
      <form>
        <Select.Root multiple onChange={mockOnChange}>
          <Select.Option value="liu-kang">Liu Kang</Select.Option>
          <Select.Option value="Jax">Jax</Select.Option>
          <Select.Option value="raiden">Raiden</Select.Option>
          <Select.Option value="scorpion">Scorpion</Select.Option>
          <Select.Option value="sub-zero">Sub Zero</Select.Option>
        </Select.Root>
      </form>
    );

    const selectEl = screen.getByRole('combobox');
    await user.click(selectEl);

    const multiSelectOption = screen.getByRole('option', {
      name: 'Liu Kang',
    });
    await user.click(multiSelectOption);
    expect(mockOnChange).toHaveBeenCalledWith(['liu-kang']);

    const multiSelectOption2 = screen.getByRole('option', {
      name: 'Jax',
    });
    await user.click(multiSelectOption2);
    expect(mockOnChange).toHaveBeenCalledWith(['liu-kang', 'Jax']);
  });
});
